import { GoPanic } from "@gotots/runtime/panic.js";
export class ProviderChannel {
    zero;
    copy;
    capacity;
    #values = [];
    #closeObservers = new Set();
    #closed = false;
    constructor(zero, copy, capacity) {
        this.zero = zero;
        this.copy = copy;
        this.capacity = capacity;
    }
    $length() {
        return this.#values.length;
    }
    $capacity() {
        return this.capacity;
    }
    receive() {
        const immediate = this.#take();
        if (immediate === undefined) {
            GoPanic.raiseRuntime("serial channel receive would block");
        }
        return immediate;
    }
    offer(value) {
        if (this.#closed) {
            return false;
        }
        const prepared = this.copy(value);
        if (this.#values.length >= this.capacity) {
            return false;
        }
        this.#values.push({ value: prepared });
        return true;
    }
    close() {
        if (this.#closed) {
            return;
        }
        this.#closed = true;
        for (const observer of this.#closeObservers) {
            observer();
        }
        this.#closeObservers.clear();
    }
    discard() {
        this.#values.splice(0);
    }
    get closed() {
        return this.#closed;
    }
    $observeClose(observer) {
        if (this.#closed) {
            observer();
            return () => undefined;
        }
        this.#closeObservers.add(observer);
        return () => {
            this.#closeObservers.delete(observer);
        };
    }
    $selectReceive(accept) {
        return {
            ready: () => this.#values.length !== 0 || this.#closed,
            commit: () => {
                const result = this.#take();
                if (result === undefined) {
                    return false;
                }
                accept(result[0], result[1]);
                return true;
            },
        };
    }
    #take() {
        const entry = this.#values.shift();
        if (entry !== undefined) {
            return [entry.value, true];
        }
        return this.#closed ? [this.zero(), false] : undefined;
    }
}
